import { renderToString } from "react-dom/server";
import { describe, expect, it } from "vitest";
import SectionedView from "./SectionedView.js";

describe("SectionedView SSR", () => {
  it("server-renders the index, the facts and every section's heading", () => {
    const html = renderToString(
      <SectionedView
        facts={<p>Facts</p>}
        header={
          <header>
            <h1>Button</h1>
          </header>
        }
        sections={[
          { id: "usage", title: "Usage", content: <p>When to use it.</p> },
          { id: "changes", title: "Changes", content: <p>What changed.</p> },
        ]}
      />,
    );
    expect(html).toContain('<article class="ds sectioned-view">');
    expect(html).toContain(
      '<ol class="ds contents-list list"><li class="entry"><a class="link" href="#usage">Usage</a></li><li class="entry"><a class="link" href="#changes">Changes</a></li></ol>',
    );
    expect(html).toContain('<div class="facts"><p>Facts</p></div>');
    expect(html).toContain(
      '<section aria-labelledby="usage" class="section"><h2 class="heading" id="usage">Usage</h2><div class="section-body"><p>When to use it.</p></div></section>',
    );
    // No section is current before a script has measured the page.
    expect(html).not.toContain("aria-current");
  });

  it("server-renders the bar first from three sections on, reading the label alone", () => {
    const html = renderToString(
      <SectionedView
        header={<h1>Button</h1>}
        sections={[
          { id: "usage", title: "Usage", content: null },
          { id: "anatomy", title: "Anatomy", content: null },
          { id: "changes", title: "Changes", content: null },
        ]}
      />,
    );
    expect(html).toMatch(
      /^<article class="ds sectioned-view"><nav aria-label="On this page" class="ds contents-bar bar" data-region="contents-bar"><details class="disclosure"><summary class="toggle"><span class="label">On this page<\/span><svg/,
    );
    expect(html).not.toContain('class="current"');
    expect(html).not.toContain("aria-current");
  });

  it("server-renders no aside for a page with no section and no facts", () => {
    const html = renderToString(
      <SectionedView header={<h1>Guide</h1>} sections={[]}>
        <p>Body</p>
      </SectionedView>,
    );
    expect(html).not.toContain('class="aside"');
    expect(html).toContain(
      '<div class="content"><div class="body"><p>Body</p></div></div>',
    );
  });
});
